import{_ as a,o as l,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"RGW Refactoring Meeting 2022-10-12","description":"","frontmatter":{"title":"RGW Refactoring Meeting 2022-10-12","date":"2022-10-12T00:00:00.000Z","updated":"2022-10-19T00:00:00.000Z","tags":["Ceph","性能测试","分布式存储","CBT","Deos"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/RGW_Refactoring_Meeting_2022-10-12.md","filePath":"posts/2022/RGW_Refactoring_Meeting_2022-10-12.md","lastUpdated":1780460162000}'),i={name:"posts/2022/RGW_Refactoring_Meeting_2022-10-12.md"};function r(s,e,n,h,u,d){return l(),o("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>本次会议重点讨论使用Ceph Benchmarking Tool（CBT）对不同后端（如DB store、Motor、Deos）进行性能比较。</p><h4 id="主要讨论内容" tabindex="-1">主要讨论内容： <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容：&quot;">​</a></h4><ol><li><p><strong>CBT的使用和目标</strong>：</p><ul><li>讨论了使用CBT进行不同后端的性能比较，特别是DB store和Deos。</li><li>提到了Deos和Motor的开发状态，以及它们是否能够通过这些工作负载。</li></ul></li><li><p><strong>Deos和Motor的状态</strong>：</p><ul><li>Deos和Motor都是开源项目，但可能需要特定的硬件支持。</li><li>Deos和Motor的后端由Seagate贡献，Intel也在其中有所参与。</li></ul></li><li><p><strong>CBT的抽象和扩展</strong>：</p><ul><li>讨论了如何改进CBT，使其不仅仅支持Ceph，还能支持其他存储系统如Deos。</li><li>提到了可能的下一步行动，包括设置Deos并构建CBT中的客户端端点。</li></ul></li><li><p><strong>性能测试和比较</strong>：</p><ul><li>讨论了如何进行性能测试，包括使用IO 500和RGW。</li><li>提到了Deos在Lenovo的IO-500测试中表现出色，尤其是在未启用复制模式下。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>计划与Seagate合作，进一步测试和集成Motor和Deos到CBT中。</li><li>计划探索如何自动化安装和部署这些存储系统。</li><li>计划与Seagate的Gregory Taretsky联系，以获取更多技术支持和合作。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了与Seagate的合作意向，并将与Gregory Taretsky联系以推进合作。</li><li>确定了初步的行动计划，包括手动安装和测试Deos和Motor，以及后续的自动化和集成工作。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>Mark将尝试手动安装Deos和Motor，并记录过程，以便后续自动化。</li><li>将与Seagate的Gregory Taretsky联系，以获取更多技术支持和合作。</li><li>将继续探索和改进CBT，使其支持更多类型的存储系统。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，感谢所有参与者的贡献和讨论。</li></ul><h4 id="修改说明" tabindex="-1">修改说明： <a class="header-anchor" href="#修改说明" aria-label="Permalink to &quot;修改说明：&quot;">​</a></h4><ul><li>在原始总结中，部分内容被错误地省略或误解。改进后的总结更准确地反映了会议的讨论要点，包括CBT的使用、Deos和Motor的状态、CBT的抽象和扩展、性能测试和比较以及后续行动计划。</li><li>保留了所有计算机科学/ceph相关领域的英文原文关键词，以确保内容的准确性和专业性。</li></ul>',13)])])}const p=a(i,[["render",r]]);export{g as __pageData,p as default};
